def solve_exact(max_solutions=1, allowrot=True):
    sols=[]; nodes=0
    @functools.lru_cache(None)
    def dfs(covered,used):
        nonlocal nodes
        nodes+=1
        if covered==mb4:
            if used==(1<<len(pieces))-1:
                return ((),)
            return ()
        # choose uncovered cell with fewest placements
        best=None; bestopts=None
        rem=mb4 & ~covered
        while rem:
            lsb=rem & -rem; idx=lsb.bit_length()-1; rem-=lsb
            poss=[]; seenpi=set()
            for pi,opt in placements_bycell[idx]:
                if (used>>pi)&1: continue
                b,r,c,oi=opt
                if not allowrot and oi!=0: continue
                if b&covered: continue
                # symmetric identical items: permit only smallest unused sibling
                group=groups[sigs[pi]]
                if pi!=min(i for i in group if not (used>>i)&1): continue
                poss.append((pi,opt))
            if bestopts is None or len(poss)<len(bestopts):
                best=idx; bestopts=poss
                if len(poss)==0: return ()
                if len(poss)==1: break
        out=[]
        for pi,opt in bestopts:
            b,r,c,oi=opt
            sub=dfs(covered|b,used|(1<<pi))
            for result in sub:
                out.append(((pi,r,c,oi),)+result)
                if len(out)>=max_solutions: return tuple(out)
        return tuple(out)
    ans=dfs(0,0)
    return ans,nodes,dfs.cache_info()
